13: struct PairedWheelSlewResult
14: {
15:   std::array<double, 2> applied;
16:   double alpha;
17: };
18: 
19: // Both wheels advance by the same fraction from current joint rim feedback.
20: // There is no retained instruction/integrator state. max_accel == 0 preserves
21: // the driver's disabled-limit semantics; otherwise sim_dt == 0 cannot advance.
22: inline PairedWheelSlewResult limit_paired_wheel_speeds(
23:   const std::array<double, 2> & current, const std::array<double, 2> & desired,
24:   double max_accel, double sim_dt)
25: {
26:   if (!std::isfinite(max_accel) || !std::isfinite(sim_dt) || max_accel < 0 || sim_dt < 0) {
27:     throw std::invalid_argument("wheel slew requires finite nonnegative acceleration/time");
28:   }
29:   for (std::size_t i = 0; i < current.size(); ++i) {
30:     if (!std::isfinite(current[i]) || !std::isfinite(desired[i])) {
31:       throw std::invalid_argument("wheel slew requires finite current/desired rim speeds");
32:     }
33:   }
34:   if (max_accel == 0) {
35:     return {desired, 1.0};
36:   }
37:   if (sim_dt == 0) {
38:     return {current, 0.0};
39:   }
40:   const std::array<long double, 2> delta{
41:     static_cast<long double>(desired[0]) - current[0],
42:     static_cast<long double>(desired[1]) - current[1]};
43:   // Directed one-ULP interval bounds on the supported native floating-point build.
44:   // A rounded long-double equality alone must not certify an exact binary64 budget.
45:   const long double budget = std::nextafter(
46:     static_cast<long double>(max_accel) * sim_dt, 0.0L);
47:   const long double largest = std::nextafter(
48:     std::max(std::abs(delta[0]), std::abs(delta[1])),
49:     std::numeric_limits<long double>::infinity());
50:   if (!std::isfinite(budget) || !std::isfinite(largest)) {
51:     throw std::invalid_argument("wheel slew arithmetic exceeds finite range");
52:   }
53:   if (largest <= budget) {
54:     return {desired, 1.0};
55:   }
56:   const auto at = [&](double alpha) {
57:       return PairedWheelSlewResult{{
58:         static_cast<double>(std::fma(static_cast<long double>(alpha), delta[0],
59:           static_cast<long double>(current[0]))),
60:         static_cast<double>(std::fma(static_cast<long double>(alpha), delta[1],
61:           static_cast<long double>(current[1])))}, alpha};
62:     };
63:   const auto within_budget = [&](const PairedWheelSlewResult & result) {
64:       return std::nextafter(std::abs(static_cast<long double>(result.applied[0]) - current[0]),
65:                std::numeric_limits<long double>::infinity()) <= budget &&
66:              std::nextafter(std::abs(static_cast<long double>(result.applied[1]) - current[1]),
67:                std::numeric_limits<long double>::infinity()) <= budget;
68:     };
69:   const long double nominal = budget / largest;
70:   // Always step the binary64 fraction inward: nominal itself is rounded in long double.
71:   double high = std::nextafter(static_cast<double>(nominal), 0.0);
72:   auto result = at(high);
73:   if (within_budget(result)) {
74:     return result;
75:   }
76:   // Round inward if binary64 output rounding would exceed either wheel's
77:   // exact acceleration budget. The same alpha still drives both wheels.
78:   double low = 0.0;
79:   for (unsigned int iteration = 0; iteration < 64; ++iteration) {
80:     const double middle = low + (high - low) / 2;
81:     if (middle == low || middle == high) {
82:       break;
83:     }
84:     if (within_budget(at(middle))) {
85:       low = middle;
86:     } else {
87:       high = middle;
88:     }
89:   }
90:   return at(low);
91: }
92: 
93: }  // namespace multi_robot
