650:     const std::array<double, 2> desired{
651:       desired_wheel_speed_[2 * i + RIGHT], desired_wheel_speed_[2 * i + LEFT]};
652:     // Start from measured joint rim speed each update. One fraction for both
653:     // wheels preserves the body-twist line segment and cannot accumulate a
