661:     joints_[2 * i + RIGHT]->SetParam(
662:       "vel", 0, limited.applied[RIGHT] / (wheel_diameter_[i] / 2.0));
663:     Audit("actuation", SimNanoseconds(_info.simTime), {
664:       {"actuation_seq", actuation_sequence_}, {"pair_index", i},
665:       {"cmd_seq", consumed_command_sequence_},
666:       {"target_decision_sequence", consumed_target_decision_sequence_},
667:       {"target_clock_ns", consumed_target_clock_ns_},
668:       {"desired_v", consumed_x_}, {"desired_w", consumed_rot_},
669:       {"dt_ns", dt_ns}, {"dt_sec", seconds_since_last_update},
670:       {"current_rim_mps", current}, {"desired_rim_mps", desired},
671:       {"applied_rim_mps", limited.applied}, {"alpha", limited.alpha},
672:       {"max_acceleration_mps2", max_wheel_accel_}});
673:   }
