678: void MR3GazeboDiffDrivePrivate::UpdateWheelVelocities()
679: {
680:   double vr = target_x_;
681:   double va = target_rot_;
682:   consumed_command_sequence_ = command_sequence_;
683:   consumed_target_decision_sequence_ = target_decision_sequence_;
684:   consumed_target_clock_ns_ = target_clock_ns_;
685:   consumed_x_ = vr;
686:   consumed_rot_ = va;
687: 
688:   for (unsigned int i = 0; i < num_wheel_pairs_; ++i) {
689:     desired_wheel_speed_[2 * i + LEFT] = vr - va * wheel_separation_[i] / 2.0;
690:     desired_wheel_speed_[2 * i + RIGHT] = vr + va * wheel_separation_[i] / 2.0;
691:   }

812: void MR3GazeboDiffDrivePrivate::UpdateOdometryWorld()
813: {
814:   auto pose = model_->WorldPose();
815:   odom_.pose.pose.position = gazebo_ros::Convert<geometry_msgs::msg::Point>(pose.Pos());
816:   odom_.pose.pose.orientation = gazebo_ros::Convert<geometry_msgs::msg::Quaternion>(pose.Rot());
817: 
818:   // Get velocity in odom frame
819:   auto linear = model_->WorldLinearVel();
820:   odom_.twist.twist.angular.z = model_->WorldAngularVel().Z();
821: 
822:   // Convert velocity to child_frame_id(aka base_footprint)
823:   float yaw = pose.Rot().Yaw();
824:   odom_.twist.twist.linear.x = cosf(yaw) * linear.X() + sinf(yaw) * linear.Y();
825:   odom_.twist.twist.linear.y = cosf(yaw) * linear.Y() - sinf(yaw) * linear.X();
